styles.873427df6ed005650a4f84982f93568ce3179b6c:
    body {
      margin: 0;
      min-height: 100vh;
      display: block;
      place-items: center;
      font-family: Arial, "Noto Sans KR", sans-serif;
      color: #172a46;
      background: #f8fafc;
    }
    main {
      max-width: 720px;
      width: calc(100vw - 32px);
      background: #fff;
      border: 1px solid #cbd5e1;
      border-radius: 10px;
      padding: 28px;
    }
    h1 { margin: 0 0 8px; font-size: 30px; }
    p { margin: 0 0 22px; color: #64748b; }
    nav { display: flex; grid-template-columns: repeat(3, 1fr); flex-wrap: wrap; }
    nav > * {
      margin-bottom: 12px;
      margin-right: 12px;
}
    nav > * {
      flex: 0 1 calc(33.333333333333336% - 12px);
      min-width: 0;
      max-width: calc(33.333333333333336% - 12px);
}
    a {
      display: block;
      border: 1px solid #9fb6d6;
      border-radius: 8px;
      padding: 18px 14px;
      text-align: center;
      color: #172a46;
      font-size: 18px;
      font-weight: 700;
      text-decoration: none;
      background: #fff;
    }
    a:hover { border-color: #2563eb; background: #f1f7ff; }
    @media (max-width: 640px) { nav { grid-template-columns: 1fr; } nav > * {
            flex: 0 1 100%;
            min-width: 0;
            max-width: 100%;
      } }

styles.0ae4943ce5f0604727e3a5faa4ead4af6a924505:
#rist-browser-warning,.rist-browser-noscript{box-sizing:border-box;max-width:1080px;margin:12px auto;padding:12px 16px;border:1px solid #d69e2e;border-radius:6px;background:#fff8df;color:#624500;font:14px/1.5 Arial,sans-serif;text-align:left;overflow-wrap:break-word;word-wrap:break-word}
#rist-browser-warning p,.rist-browser-noscript p{margin:4px 0;color:#624500;font:inherit}
#rist-browser-warning.rist-compat-notice{max-width:none;margin:0;padding:8px 20px;border-radius:0;border-color:#b9cde3;background:#eef5fc;color:#254563;font-size:12px}
#rist-browser-warning.rist-compat-notice p{color:#254563}
#rist-browser-warning.rist-compat-notice p~p{display:none}
@media(max-width:640px){#rist-browser-warning,.rist-browser-noscript{margin:8px;padding:10px 12px}}
@media print{#rist-browser-warning,.rist-browser-noscript{display:none!important}}

styles.4cbd70099bcf44e89c7fa049ae4ef903e390d4c9:
html, body {
  margin: 0;
  min-height: 100%;
  background: #f8fafc;
  color: #1f2933;
  font-family: Arial, "Noto Sans KR", sans-serif;
}
body {
  overflow-x: hidden;
}
.ftir-app-bar {
  display: flex;
  align-items: center;
  min-height: 54px;
  padding: 0 22px;
  border-bottom: 1px solid #d9e2ec;
  background: #ffffff;
  box-sizing: border-box;
}
.ftir-brand {
  display: flex;
  align-items: baseline;
  min-width: 0;
}
.ftir-brand > * {
  margin-bottom: 9px;
  margin-right: 9px;
}
.ftir-brand strong {
  color: #102a43;
  font-size: 18px;
  letter-spacing: 0;
}
.ftir-brand span {
  color: #52606d;
  font-size: 12px;
}
.ftir-app-actions {
  display: flex;
  align-items: center;
  margin-left: auto;
}
.ftir-app-actions > * {
  margin-bottom: 8px;
  margin-right: 8px;
}
.ftir-origin-toggle {
  display: inline-flex;
  align-items: center;
  height: 30px;
  padding: 0 8px;
  border: 1px solid #9fb3c8;
  border-radius: 4px;
  background: #fff;
  color: #243b53;
  cursor: pointer;
  font-size: 11px;
  white-space: nowrap;
  box-sizing: border-box;
}
.ftir-origin-toggle > * {
  margin-bottom: 5px;
  margin-right: 5px;
}
.ftir-origin-toggle input {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: #2563eb;
}
.ftir-status {
  max-width: 360px;
  overflow: hidden;
  color: #52606d;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ftir-file-button,
.ftir-clear-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 30px;
  border: 1px solid #9fb3c8;
  border-radius: 4px;
  background: #f5f7fa;
  color: #243b53;
  cursor: pointer;
  font-size: 11px;
  padding: 0 10px;
  box-sizing: border-box;
  text-decoration: none;
  white-space: nowrap;
}
.ftir-file-button:hover,
.ftir-clear-button:hover {
  border-color: #486581;
  background: #e8eef5;
}
.ftir-clear-button[hidden] {
  display: none;
}
.ftir-file-input {
  display: none;
}
.ftir-library-band {
  display: flex;
  align-items: flex-start;
  min-height: 68px;
  padding: 7px 22px;
  border-bottom: 1px solid #d9e2ec;
  background: #f8fafc;
  box-sizing: border-box;
}
.ftir-library-band > * {
  margin-bottom: 10px;
  margin-right: 10px;
}
.ftir-library-title {
  flex: 0 0 auto;
  margin-top: 9px;
  color: #334e68;
  font-size: 11px;
  font-weight: 700;
}
.ftir-library-filter {
  flex: 0 0 150px;
  width: 150px;
  height: 30px;
  margin-top: 0;
  border: 1px solid #bcccdc;
  border-radius: 4px;
  background: #ffffff;
  color: #243b53;
  font: 11px Arial, "Noto Sans KR", sans-serif;
  padding: 0 9px;
  box-sizing: border-box;
}
.ftir-library-list {
  display: flex;
  align-content: flex-start;
  align-items: flex-start;
  flex-wrap: wrap;
  min-width: 0;
  flex: 1 1 auto;
  max-height: 62px;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 0 2px 1px 0;
}
.ftir-library-list > * {
  margin-bottom: 6px;
  margin-right: 6px;
}
.ftir-library-item {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  max-width: 300px;
  height: 28px;
  border: 1px solid #bcccdc;
  border-radius: 4px;
  background: #ffffff;
  color: #334e68;
  font-size: 11px;
  box-sizing: border-box;
}
.ftir-library-item.is-selected {
  border-color: #3e7ca6;
  background: #edf6fb;
  color: #174b6d;
}
.ftir-library-item.is-invalid {
  border-color: #f5b7b1;
  background: #fff5f5;
  color: #9b2c2c;
}
.ftir-library-toggle {
  display: inline-flex;
  align-items: center;
  height: 100%;
  padding-left: 8px;
}
.ftir-library-toggle input {
  margin: 0;
}
.ftir-library-name {
  min-width: 0;
  max-width: 210px;
  height: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  overflow: hidden;
  padding: 0 6px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ftir-library-name:hover {
  text-decoration: underline;
}
.ftir-library-count {
  color: #7b8794;
  font-size: 10px;
  padding-right: 5px;
}
.ftir-library-state {
  border-left: 1px solid #d9e2ec;
  color: #7b8794;
  font-size: 9px;
  padding: 0 6px;
  white-space: nowrap;
}
.ftir-library-item.is-selected .ftir-library-state {
  color: #17633a;
  font-weight: 700;
}
.ftir-library-empty {
  color: #7b8794;
  font-size: 11px;
  white-space: nowrap;
}
.ftir-library-upload {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  height: 30px;
  margin-top: 0;
  border: 1px solid #9fb3c8;
  border-radius: 4px;
  background: #ffffff;
  color: #243b53;
  cursor: pointer;
  font-size: 11px;
  padding: 0 10px;
  box-sizing: border-box;
}
.ftir-library-new {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  height: 30px;
  margin-top: 0;
  border: 1px solid #3e7ca6;
  border-radius: 4px;
  background: #edf6fb;
  color: #174b6d;
  cursor: pointer;
  font-size: 11px;
  padding: 0 10px;
  box-sizing: border-box;
}
.ftir-library-new:hover {
  background: #dceef8;
}
.ftir-library-upload:hover {
  border-color: #486581;
  background: #eef2f6;
}
.ftir-library-modal {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 90;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(15, 23, 42, 0.34);
  box-sizing: border-box;
}
.ftir-library-modal.is-visible {
  display: flex;
}
.ftir-library-dialog {
  display: flex;
  flex-direction: column;
  max-width: 880px;
  width: 100%;
  max-height: 78vh;
  max-height: min(78dvh, 720px);
  border: 1px solid #9fb3c8;
  border-radius: 6px;
  background: #ffffff;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.22);
  overflow: hidden;
}
.ftir-library-dialog-header {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  min-height: 48px;
  padding: 0 14px;
  border-bottom: 1px solid #d9e2ec;
  background: #f8fafc;
  box-sizing: border-box;
}
.ftir-library-dialog-header > * {
  margin-bottom: 10px;
  margin-right: 10px;
}
.ftir-library-dialog-heading {
  min-width: 0;
}
.ftir-library-dialog-heading strong {
  display: block;
  overflow: hidden;
  color: #102a43;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ftir-library-dialog-heading span {
  display: block;
  overflow: hidden;
  color: #627d98;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ftir-library-dialog-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  margin-left: auto;
  border: 0;
  background: transparent;
  color: #52606d;
  cursor: pointer;
  font: 20px/1 Arial, sans-serif;
}
.ftir-library-dialog-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 12px 14px 0;
}
.ftir-library-form-meta {
  display: flex;
  grid-template-columns: minmax(150px, 0.7fr) minmax(220px, 1fr);
  margin-bottom: 12px;
  flex-wrap: wrap;
}
.ftir-library-form-meta > * {
  margin-bottom: 10px;
  margin-right: 12px;
}
.ftir-library-form-meta > * {
  flex: 0 1 calc(50% - 12px);
  min-width: 0;
  max-width: calc(50% - 12px);
}
.ftir-library-suggest {
  flex-basis: 100%;
  max-width: 100%;
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  min-width: 0;
  padding: 5px 6px;
  border: 1px solid #d9e2ec;
  border-radius: 4px;
  background: #f8fafc;
  box-sizing: border-box;
}
.ftir-library-suggest > * {
  margin-bottom: 6px;
  margin-right: 6px;
}
.ftir-library-suggest input {
  flex: 1 1 220px;
  min-width: 0;
  height: 28px;
  border: 1px solid #bcccdc;
  border-radius: 3px;
  background: #ffffff;
  color: #243b53;
  font: 11px Arial, "Noto Sans KR", sans-serif;
  padding: 0 7px;
  box-sizing: border-box;
}
.ftir-library-suggest button {
  flex: 0 0 auto;
  height: 28px;
  border: 1px solid #3e7ca6;
  border-radius: 4px;
  background: #edf6fb;
  color: #174b6d;
  cursor: pointer;
  font-size: 11px;
  padding: 0 10px;
}
.ftir-library-suggest button:disabled {
  cursor: progress;
  opacity: 0.65;
}
.ftir-library-suggest span {
  flex: 0 1 auto;
  color: #7b8794;
  font-size: 10px;
  white-space: nowrap;
}
.ftir-library-spectrum-preview {
  margin: 0 0 12px;
  padding: 10px 12px;
  border: 1px solid #d9e2ec;
  border-radius: 4px;
  background: #fbfdff;
  box-sizing: border-box;
}
.ftir-library-spectrum-preview-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 6px;
  color: #102a43;
  font-size: 12px;
  font-weight: 700;
}
.ftir-library-spectrum-preview-head > * {
  margin-bottom: 10px;
  margin-right: 10px;
}
.ftir-library-spectrum-preview-head span {
  color: #627d98;
  font-size: 10px;
  font-weight: 400;
}
.ftir-library-spectrum-preview svg {
  display: block;
  width: 100%;
  height: 174px;
}
.ftir-library-match-preview {
  margin: 0 0 12px;
  padding: 10px 12px;
  border: 1px solid #d9e2ec;
  border-radius: 4px;
  background: #ffffff;
  box-sizing: border-box;
}
.ftir-library-match-preview-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
  color: #102a43;
  font-size: 12px;
  font-weight: 700;
}
.ftir-library-match-preview-head > * {
  margin-bottom: 10px;
  margin-right: 10px;
}
.ftir-library-match-preview-head span {
  color: #627d98;
  font-size: 10px;
  font-weight: 400;
}
.ftir-library-match-grid {
  display: flex;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  flex-wrap: wrap;
}
.ftir-library-match-grid > * {
  margin-bottom: 8px;
  margin-right: 8px;
}
.ftir-library-match-grid > * {
  flex: 0 1 calc(50% - 8px);
  min-width: 0;
  max-width: calc(50% - 8px);
}
.ftir-library-match-card {
  min-width: 0;
  padding: 8px;
  border: 1px solid #e4e7eb;
  border-radius: 4px;
  background: #f8fafc;
}
.ftir-library-match-card strong {
  display: block;
  overflow: hidden;
  color: #102a43;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ftir-library-match-score {
  margin: 4px 0 3px;
  color: #1f6f50;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.1;
}
.ftir-library-match-card span {
  display: block;
  color: #52606d;
  font-size: 10px;
}
.ftir-library-match-list {
  margin: 8px 0 0;
  padding-left: 16px;
  color: #334e68;
  font-size: 10px;
}
.ftir-library-match-list li {
  margin: 3px 0;
}
.ftir-library-match-empty {
  color: #829ab1;
  font-size: 11px;
}
.ftir-library-field {
  display: flex;
  flex-direction: column;
  min-width: 0;
  color: #52606d;
  font-size: 10px;
}
.ftir-library-field > * {
  margin-bottom: 4px;
  margin-right: 4px;
}
.ftir-library-field.is-wide {
  flex-basis: 100%;
  max-width: 100%;
  grid-column: 1 / -1;
}
.ftir-library-field input,
.ftir-library-field textarea,
.ftir-library-table input {
  width: 100%;
  border: 1px solid #bcccdc;
  border-radius: 3px;
  background: #ffffff;
  color: #243b53;
  font: 11px Arial, "Noto Sans KR", sans-serif;
  padding: 6px 7px;
  box-sizing: border-box;
}
.ftir-library-field input:disabled {
  background: #eef2f6;
  color: #627d98;
}
.ftir-library-field textarea {
  min-height: 52px;
  resize: vertical;
}
.ftir-library-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  color: #243b53;
  font-size: 11px;
}
.ftir-library-table th {
  position: relative;
  top: 0;
  z-index: 1;
  padding: 8px;
  border-bottom: 1px solid #bcccdc;
  background: #eef2f6;
  color: #334e68;
  text-align: left;
}
.ftir-library-table td {
  padding: 7px 8px;
  border-bottom: 1px solid #e4e7eb;
  vertical-align: top;
  overflow-wrap: anywhere;
}
.ftir-library-table input[type="number"] {
  text-align: right;
}
.ftir-library-table input[type="color"] {
  width: 34px;
  min-width: 34px;
  height: 28px;
  padding: 2px;
}
.ftir-library-table .numeric {
  width: 90px;
  text-align: right;
}
.ftir-library-table .color {
  width: 48px;
}
.ftir-library-table .remove {
  width: 42px;
  text-align: center;
}
.ftir-library-row-remove {
  width: 26px;
  height: 26px;
  border: 0;
  background: transparent;
  color: #7b8794;
  cursor: pointer;
  font: 17px/1 Arial, sans-serif;
}
.ftir-library-row-remove:hover {
  color: #b42318;
}
.ftir-library-swatch {
  display: inline-block;
  width: 16px;
  height: 16px;
  margin-right: 5px;
  border: 1px solid rgba(0,0,0,0.18);
  border-radius: 3px;
  vertical-align: middle;
}
.ftir-library-dialog-loading {
  padding: 28px 16px;
  color: #627d98;
  font-size: 12px;
  text-align: center;
}
.ftir-library-dialog-footer {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  min-height: 50px;
  padding: 8px 14px;
  border-top: 1px solid #d9e2ec;
  background: #f8fafc;
  box-sizing: border-box;
}
.ftir-library-dialog-footer > * {
  margin-bottom: 8px;
  margin-right: 8px;
}
.ftir-library-dialog-footer-actions {
  display: flex;
  margin-left: auto;
}
.ftir-library-dialog-footer-actions > * {
  margin-bottom: 8px;
  margin-right: 8px;
}
.ftir-library-dialog-button {
  height: 30px;
  border: 1px solid #9fb3c8;
  border-radius: 4px;
  background: #ffffff;
  color: #243b53;
  cursor: pointer;
  font-size: 11px;
  padding: 0 11px;
}
.ftir-library-dialog-button.primary {
  border-color: #2f6f9f;
  background: #2f6f9f;
  color: #ffffff;
}
.ftir-library-dialog-button.danger {
  border-color: #ba2525;
  background: #fff5f5;
  color: #9b1c1c;
}
.ftir-library-dialog-button.danger:hover {
  background: #ffe3e3;
}
.ftir-library-dialog-button:disabled {
  cursor: default;
  opacity: 0.55;
}
.ftir-drop-band {
  display: flex;
  align-items: center;
  min-height: 48px;
  padding: 7px 22px;
  border-bottom: 1px solid #d9e2ec;
  background: #ffffff;
  box-sizing: border-box;
  transition: background-color 120ms ease, border-color 120ms ease;
}
.ftir-drop-band.is-dragging {
  border-color: #2f855a;
  background: #f0fff4;
}
.ftir-drop-prompt {
  color: #627d98;
  font-size: 11px;
  white-space: nowrap;
}
.ftir-file-list {
  display: flex;
  align-items: center;
  min-width: 0;
  overflow-x: auto;
}
.ftir-file-list > * {
  margin-bottom: 6px;
  margin-right: 6px;
}
.ftir-file-item {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  height: 28px;
  border: 1px solid #bcccdc;
  border-radius: 4px;
  background: #f5f7fa;
  color: #334e68;
  font-size: 11px;
  padding-left: 8px;
}
.ftir-file-remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 27px;
  height: 26px;
  border: 0;
  background: transparent;
  color: #7b8794;
  cursor: pointer;
  font: 16px/1 Arial, sans-serif;
  padding: 0;
}
.ftir-file-remove:hover {
  color: #b42318;
}
.ftir-report-meta-band {
  border-bottom: 1px solid #d9e2ec;
  background: #f8fafc;
}
.ftir-report-meta-panel {
  padding: 0 22px;
}
.ftir-report-meta-panel > summary {
  display: flex;
  align-items: center;
  min-height: 34px;
  color: #334e68;
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
  list-style: none;
}
.ftir-report-meta-panel > summary > * {
  margin-bottom: 8px;
  margin-right: 8px;
}
.ftir-report-meta-panel > summary::-webkit-details-marker {
  display: none;
}
.ftir-report-meta-panel > summary::before {
  content: "+";
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border: 1px solid #9fb3c8;
  border-radius: 3px;
  color: #52606d;
  font-size: 12px;
  line-height: 1;
}
.ftir-report-meta-panel[open] > summary::before {
  content: "-";
}
.ftir-report-meta-panel > summary span {
  color: #7b8794;
  font-size: 10px;
  font-weight: 400;
}
.ftir-report-meta-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
