    :root {
      color-scheme: light;
      --ink: #172a46;
      --muted: #64748b;
      --line: #cbd5e1;
      --blue: #2563eb;
      --green: #16a34a;
      --bg: #f8fafc;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Arial, "Noto Sans KR", sans-serif;
      color: var(--ink);
      background: var(--bg);
    }
    .xrd-shell { min-height: 100vh; display: flex; flex-direction: column; }
    .xrd-topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 24px 28px;
      border-bottom: 1px solid var(--line);
      background: #fff;
    }
    .xrd-topbar > * {
      margin-bottom: 16px;
      margin-right: 16px;
}
    .xrd-brand { display: flex; align-items: baseline; min-width: 0; }
    .xrd-brand > * {
      margin-bottom: 14px;
      margin-right: 14px;
}
    .xrd-brand h1 { margin: 0; font-size: 30px; letter-spacing: 0; }
    .xrd-brand span { color: var(--muted); font-size: 17px; white-space: nowrap; }
    .xrd-actions { display: flex; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
    .xrd-actions > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    button, .xrd-download {
      border: 1px solid #9fb6d6;
      background: #fff;
      color: var(--ink);
      border-radius: 7px;
      min-height: 42px;
      padding: 9px 14px;
      font-size: 15px;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
    }
    button.primary { border-color: var(--blue); background: var(--blue); color: #fff; }
    button:disabled, .xrd-download[aria-disabled="true"] {
      opacity: .48;
      cursor: not-allowed;
      pointer-events: none;
    }
    .xrd-main { padding: 18px 28px 28px; display: block; }
    .xrd-main > * {
      margin-bottom: 16px;
}
    .xrd-panel {
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 16px;
    }
    .xrd-hidden-input { display: none; }
    .xrd-check {
      display: flex;
      align-items: center;
      min-height: 42px;
      font-weight: 700;
    }
    .xrd-check > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .xrd-drop {
      border: 1px dashed #9fb6d6;
      border-radius: 8px;
      min-height: 122px;
      color: #476483;
      background: #f8fbff;
      text-align: center;
      padding: 18px;
      display: block;
      place-items: center;
    }
    .xrd-drop.dragover { border-color: var(--blue); background: #eef6ff; }
    .xrd-drop-title {
      margin: 0 0 5px;
      color: var(--ink);
      font-size: 18px;
      font-weight: 800;
    }
    .xrd-drop-text { margin: 0; color: #476483; line-height: 1.45; }
    .xrd-bundle-actions {
      margin-top: 13px;
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      align-items: center;
    }
    .xrd-bundle-actions > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .xrd-bundle-actions button { min-height: 38px; padding: 7px 12px; font-size: 14px; }
    .xrd-bundle-meta {
      margin-top: 10px;
      color: var(--muted);
      font-size: 13px;
      text-align: center;
    }
    .xrd-files {
      margin-top: 12px;
      display: flex;
      flex-wrap: wrap;
    }
    .xrd-files > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .xrd-chip {
      border: 1px solid var(--line);
      border-radius: 999px;
      padding: 6px 10px;
      background: #fff;
      color: #334155;
      font-size: 13px;
      max-width: 280px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .xrd-status-stack {
      display: block;
    }
    .xrd-status-stack > * {
      margin-bottom: 8px;
}
    .xrd-status {
      min-height: 38px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 8px 10px 8px 12px;
      border-radius: 7px;
      background: #ecfdf5;
      border: 1px solid #bbf7d0;
      color: #166534;
      font-size: 14px;
      transition: opacity 180ms ease, transform 180ms ease;
    }
    .xrd-status > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .xrd-status.error { background: #fef2f2; border-color: #fecaca; color: #991b1b; }
    .xrd-status.is-hiding { opacity: 0; transform: translateY(-4px); }
    .xrd-status-text { min-width: 0; overflow-wrap: anywhere; }
    .xrd-status-close {
      min-height: 0;
      border: 0;
      background: transparent;
      color: currentColor;
      cursor: pointer;
      font-size: 17px;
      font-weight: 800;
      line-height: 1;
      padding: 2px 4px;
      opacity: .72;
    }
    .xrd-status-close:hover { opacity: 1; background: rgba(15, 23, 42, .06); }
    .xrd-progress {
      display: none;
      padding: 11px 14px 12px;
      border: 1px solid #bfdbfe;
      border-radius: 8px;
      background: #eff6ff;
      color: #1e3a8a;
      font-size: 13px;
    }
    .xrd-progress.is-visible {
      position: fixed;
      left: 50%;
      top: 50%;
      z-index: 70;
      display: block;
      max-width: 560px;
      width: calc(100vw - 32px);
      transform: translate(-50%, -50%);
      box-shadow: 0 18px 48px rgba(15, 23, 42, 0.18);
    }
    .xrd-progress.is-visible > * {
      margin-bottom: 11px;
}
    .xrd-progress.is-error {
      border-color: #fecaca;
      background: #fef2f2;
      color: #991b1b;
    }
    .xrd-progress-stage { display: none; }
    .xrd-progress-stage.is-visible { display: block; }
    .xrd-report-progress-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 7px;
      font-weight: 700;
    }
    .xrd-report-progress-row > * {
      margin-bottom: 12px;
      margin-right: 12px;
}
    .xrd-report-progress-track {
      overflow: hidden;
      height: 7px;
      border-radius: 999px;
      background: #dbeafe;
    }
    .xrd-report-progress-bar {
      width: 0%;
      height: 100%;
      border-radius: inherit;
      background: var(--blue);
      transition: width 240ms ease;
    }
    .xrd-upload-progress .xrd-report-progress-bar { background: #16a34a; }
    .xrd-progress.is-error .xrd-report-progress-bar { background: #dc2626; }
    .xrd-preview {
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 8px;
      overflow: hidden;
      min-height: 720px;
    }
    .xrd-preview iframe {
      width: 100%;
      height: 920px;
      border: 0;
      display: block;
      background: #fff;
    }
    .xrd-transfer {
      display: block;
      padding: 16px;
      border: 1px solid var(--line);
      border-radius: 8px;
      background: #fff;
    }
    .xrd-transfer > * {
      margin-bottom: 12px;
}
    .xrd-transfer-head,
    .xrd-transfer-actions {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
    }
    .xrd-transfer-head > *,.xrd-transfer-actions > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .xrd-transfer-head strong { color: var(--ink); }
    .xrd-request-picker {
      display: flex;
      grid-template-columns: auto minmax(240px, 1fr);
      flex-wrap: wrap;
    }
    .xrd-request-picker > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .xrd-request-picker > * {
      flex: 0 1 calc(50% - 10px);
      min-width: 0;
      max-width: calc(50% - 10px);
}
    .xrd-request-picker select,
    .xrd-transfer-grid input {
      width: 100%;
      min-width: 0;
      min-height: 40px;
      border: 1px solid #bfd0e4;
      border-radius: 6px;
      background: #fff;
      color: var(--ink);
      padding: 8px 10px;
      font: inherit;
    }
    .xrd-request-detail {
      display: flex;
      flex-wrap: wrap;
      min-height: 22px;
      color: #475569;
      font-size: 13px;
    }
    .xrd-request-detail > * {
      margin-bottom: 7px;
      margin-right: 14px;
}
    .xrd-request-detail.is-empty { color: var(--muted); }
    .xrd-request-detail b { margin-right: 4px; color: #1e3a5f; }
    .xrd-transfer-grid {
      display: flex;
      grid-template-columns: repeat(4, minmax(150px, 1fr));
      flex-wrap: wrap;
    }
    .xrd-transfer-grid > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .xrd-transfer-grid > * {
      flex: 0 1 calc(25% - 10px);
      min-width: 0;
      max-width: calc(25% - 10px);
}
    .xrd-transfer-grid label { min-width: 0; color: #475569; font-size: 13px; }
    .xrd-transfer-grid span { display: block; margin-bottom: 5px; font-weight: 700; }
    .xrd-empty {
      height: 720px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--muted);
      font-weight: 700;
    }
    .xrd-busy {
      position: fixed;
      top: 0;
      right: 0;
      bottom: 0;
      left: 0;
      display: none;
      align-items: center;
      justify-content: center;
      background: rgba(255,255,255,.74);
      z-index: 50;
      color: var(--ink);
      font-weight: 700;
    }
    .xrd-busy.show { display: flex; }
    @media (max-width: 900px) {
      .xrd-topbar { align-items: flex-start; padding: 18px 16px; }
      .xrd-brand { display: block; }
      .xrd-brand h1 { font-size: 25px; }
      .xrd-brand span { display: block; margin-top: 4px; white-space: normal; }
      .xrd-main { padding: 14px 12px 24px; }
      .xrd-actions { width: 100%; justify-content: flex-end; }
      button, .xrd-download { min-height: 40px; padding: 8px 11px; font-size: 14px; }
      .xrd-preview iframe { height: 780px; }
      .xrd-request-picker { grid-template-columns: 1fr; }
      .xrd-request-picker > * {
            flex: 0 1 100%;
            min-width: 0;
            max-width: 100%;
      }
      .xrd-transfer-grid { grid-template-columns: repeat(2, minmax(120px, 1fr)); }
      .xrd-transfer-grid > * {
            flex: 0 1 calc(50% - 12px);
            min-width: 0;
            max-width: calc(50% - 12px);
      }
    }

