@media(max-width:640px){.top{padding:12px 14px}.top .top-actions{width:100%}.wrap{padding:14px}.tab{padding:10px 8px;font-size:13px}.stats,.filters,.meta{grid-template-columns:1fr 1fr}.stats > *,.filters > *,.meta > *{flex:0 1 calc(50% - 12px);min-width:0;max-width:calc(50% - 12px)}.date-range,.filters #query,.filters #cleanup-preview{flex-basis:100%;max-width:100%;grid-column:1/-1}.multi-menu{position:fixed;left:14px;right:14px;top:auto;min-width:0}.bulk .policy-button{margin-left:0}.pager{justify-content:center;flex-wrap:wrap}.page-numbers{order:3;width:100%;justify-content:center}.detail{top:0;right:0;bottom:0;left:0;width:100%;max-width:none;border:0}.artifact{grid-template-columns:70px 1fr}.artifact > *{flex:0 1 calc(50% - 12px);min-width:0;max-width:calc(50% - 12px)}.artifact span:last-child{grid-column:2}.head{display:block}.policy-row{grid-template-columns:1fr 105px}.policy-row > *{flex:0 1 calc(50% - 12px);min-width:0;max-width:calc(50% - 12px)}.policy-row>div:first-child{flex-basis:100%;max-width:100%;grid-column:1/-1}.policy-modal{width:100%;max-height:100vh;border-radius:0}}
@media(max-width:440px){.date-range{grid-template-columns:1fr}.date-range > *{flex:0 1 100%;min-width:0;max-width:100%}.date-range .date-clear{width:100%}}
